addedCss:
/* Warm question-desk ground separates Miss Jeeves from her navy clothes. */
#reference{background:linear-gradient(115deg,var(--hp-pink),var(--hp-coral) 55%,var(--hp-orange));color:var(--hp-ink)}
#reference::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;border-radius:inherit;background:url('/assets/homepage/pattern-retro-print-v2.png') center/560px auto repeat;filter:grayscale(1) brightness(1.076) contrast(1.529);mix-blend-mode:multiply;opacity:.09}
#reference :is(p,label,.jeeves-examples>span,.jeeves-answer h3,.jeeves-answer summary),#reference a{color:var(--hp-ink)}
#reference h2{color:#451b78}
#reference input{background:var(--hp-orange);color:var(--hp-ink);box-shadow:inset 0 0 0 2px var(--hp-ink)}
#reference form button{background:var(--hp-ink);color:var(--hp-pink)}
#reference .jeeves-examples button{background:var(--hp-orange);border-color:var(--hp-ink);color:var(--hp-ink)}
#reference .jeeves-examples button:nth-of-type(2){background:var(--hp-coral)}
#reference .jeeves-examples button:nth-of-type(3){background:var(--hp-pink)}
#reference .jeeves-examples button:hover,#reference .jeeves-examples button:focus-visible{background:var(--hp-ink);color:var(--hp-orange)}
#reference .jeeves-answer{border-color:var(--hp-ink)}
#reference .jeeves-answer li{border-color:var(--hp-ink)}
#reference .jeeves-answer button{background:var(--hp-ink);color:var(--hp-orange)}
#reference :is(a,button,input,summary):focus-visible{outline:3px solid var(--hp-ink);outline-offset:4px}
/* Match the chosen directory heading: Jost Bold, retaining compact banner sizes. */
.dyk-slim h2,.dyk-slim .dyk-copy :is(h3,.dyk-title,.dyk-cta),.dyk-slim .dyk-controls button{font-family:Jost,sans-serif;font-weight:700;font-style:normal}
